def cmp_semver(a, b):
    def parse(v):
        v = v.split('+', 1)[0]
        if '-' in v:
            core, pre = v.split('-', 1)
        else:
            core, pre = v, None
        parts = tuple(int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return parts, pre_ids

    def cmp_num(x, y):
        return (x > y) - (x < y)

    (a_core, a_pre) = parse(a)
    (b_core, b_pre) = parse(b)

    c = cmp_num(a_core, b_core)
    if c != 0:
        return c

    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None and b_pre is not None:
        return 1
    if a_pre is not None and b_pre is None:
        return -1

    for x, y in zip(a_pre, b_pre):
        x_num = x.isdigit()
        y_num = y.isdigit()
        if x_num and y_num:
            c = cmp_num(int(x), int(y))
            if c != 0:
                return c
        elif x_num and not y_num:
            return -1
        elif not x_num and y_num:
            return 1
        else:
            c = cmp_num(x, y)
            if c != 0:
                return c

    return cmp_num(len(a_pre), len(b_pre))
```

