import re


def _translate_simple(s):
    """Translate a gitignore pattern fragment (no '**') into a regex string."""
    res = []
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c == '*':
            res.append('[^/]*')
            i += 1
        elif c == '?':
            res.append('[^/]')
            i += 1
        elif c == '[':
            j = i + 1
            if j < n and s[j] == '!':
                j += 1
            if j < n and s[j] == ']':
                j += 1
            while j < n and s[j] != ']':
                j += 1
            if j >= n:
                res.append(re.escape('['))
                i += 1
            else:
                content = s[i + 1:j]
                if content.startswith('!'):
                    content = '^' + content[1:]
                res.append('[' + content + ']')
                i = j + 1
        else:
            res.append(re.escape(c))
            i += 1
    return ''.join(res)


def _translate(pat):
    """Translate a full (already de-anchored, de-slash-suffixed) pattern to regex."""
    if pat == '**':
        return '.*'

    prefix = ''
    body = pat
    if body.startswith('**/'):
        prefix = '(?:.*/)?'
        body = body[3:]

    suffix = ''
    if body.endswith('/**'):
        suffix = '(?:/.*)?'
        body = body[:-3]

    return prefix + _translate_simple(body) + suffix


def gitignore_match(pattern, path):
    dir_only = pattern.endswith('/')
    pat = pattern[:-1] if dir_only else pattern

    is_dir = path.endswith('/')
    if dir_only and not is_dir:
        return False

    anchored = pat.startswith('/') or ('/' in pat)
    if pat.startswith('/'):
        pat = pat[1:]

    regex_str = _translate(pat)
    compiled = re.compile(regex_str)

    # Strip trailing slash from path for content matching purposes.
    content = path[:-1] if is_dir else path

    if anchored:
        return compiled.fullmatch(content) is not None
    else:
        starts = [0]
        for idx, c in enumerate(content):
            if c == '/':
                starts.append(idx + 1)
        for start in starts:
            sub = content[start:]
            if compiled.fullmatch(sub):
                return True
        return False
