def parse_range(header, size):
    if not header or size <= 0:
        return None

    header = header.strip()
    if not header.startswith("bytes="):
        return None

    spec = header[len("bytes="):].strip()
    if not spec:
        return None

    raw_ranges = spec.split(",")
    results = []

    for raw in raw_ranges:
        raw = raw.strip()
        if not raw:
            continue

        if "-" not in raw:
            return None

        start_str, _, end_str = raw.partition("-")
        start_str = start_str.strip()
        end_str = end_str.strip()

        if start_str == "" and end_str == "":
            return None

        try:
            if start_str == "":
                # suffix range: last N bytes
                suffix_len = int(end_str)
                if suffix_len < 0:
                    return None
                if suffix_len == 0:
                    # unsatisfiable
                    continue
                if suffix_len >= size:
                    start = 0
                else:
                    start = size - suffix_len
                end = size - 1
            else:
                start = int(start_str)
                if start < 0:
                    return None

                if start >= size:
                    # unsatisfiable
                    continue

                if end_str == "":
                    end = size - 1
                else:
                    end = int(end_str)
                    if end < 0:
                        return None
                    if end < start:
                        # unsatisfiable
                        continue
                    if end > size - 1:
                        end = size - 1

        except ValueError:
            return None

        results.append((start, end))

    if not results:
        return None

    return results
