def unified_diff(a, b, context=3):
    n, m = len(a), len(b)
    # LCS via DP
    dp = [[0]*(m+1) for _ in range(n+1)]
    for i in range(n-1, -1, -1):
        for j in range(m-1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = dp[i+1][j+1] + 1
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j+1])

    # Build opcodes
    opcodes = []
    i = j = 0
    while i < n and j < m:
        if a[i] == b[j]:
            i0, j0 = i, j
            while i < n and j < m and a[i] == b[j]:
                i += 1
                j += 1
            opcodes.append(('equal', i0, i, j0, j))
        else:
            i0, j0 = i, j
            if dp[i+1][j] >= dp[i][j+1]:
                while i < n and j < m and a[i] != b[j] and dp[i+1][j] >= dp[i][j+1]:
                    i += 1
            else:
                while i < n and j < m and a[i] != b[j] and dp[i][j+1] > dp[i+1][j]:
                    j += 1
            if i == i0 and j == j0:
                # forced single step fallback
                if dp[i+1][j] >= dp[i][j+1]:
                    i += 1
                else:
                    j += 1
            opcodes.append(('replace', i0, i, j0, j))
    if i < n:
        opcodes.append(('delete', i, n, j, j))
        i = n
    if j < m:
        opcodes.append(('insert', i, i, j, m))
        j = m

    # merge adjacent opcodes of same tag (shouldn't happen but just in case)
    merged = []
    for op in opcodes:
        if merged and merged[-1][0] == op[0] and merged[-1][2] == op[1] and merged[-1][4] == op[3]:
            tag = merged[-1][0]
            merged[-1] = (tag, merged[-1][1], op[2], merged[-1][3], op[4])
        else:
            merged.append(list(op))
    opcodes = [tuple(o) for o in merged]

    if all(op[0] == 'equal' for op in opcodes):
        return []

    # group into hunks with context
    groups = []
    cur_group = []
    nops = len(opcodes)
    for idx, (tag, i1, i2, j1, j2) in enumerate(opcodes):
        if tag == 'equal':
            if not cur_group:
                # leading equal: trim to last `context` lines, but only keep if next op exists
                if idx == nops - 1:
                    continue
                start = max(i1, i2 - context)
                if start < i2:
                    cur_group.append(('equal', start, i2, j1 + (start - i1), j2))
                continue
            else:
                # trailing equal within a group: split
                if i2 - i1 <= 2 * context:
                    cur_group.append((tag, i1, i2, j1, j2))
                    continue
                else:
                    end = min(i2, i1 + context)
                    cur_group.append(('equal', i1, end, j1, j1 + (end - i1)))
                    groups.append(cur_group)
                    cur_group = []
                    start = max(i1, i2 - context)
                    if start < i2 and idx != nops - 1:
                        cur_group.append(('equal', start, i2, j1 + (start - i1), j2))
                    continue
        else:
            cur_group.append((tag, i1, i2, j1, j2))
    if cur_group:
        # remove if only equal ops
        if any(op[0] != 'equal' for op in cur_group):
            groups.append(cur_group)

    lines = []
    for group in groups:
        i1 = group[0][1]
        i2 = group[-1][2]
        j1 = group[0][3]
        j2 = group[-1][4]

        alen = i2 - i1
        blen = j2 - j1
        astart = i1 + 1 if alen > 0 else i1
        bstart = j1 + 1 if blen > 0 else j1

        lines.append("@@ -%d,%d +%d,%d @@" % (astart, alen, bstart, blen))
        for tag, i1_, i2_, j1_, j2_ in group:
            if tag == 'equal':
                for k in range(i1_, i2_):
                    lines.append(" " + a[k])
            elif tag == 'delete':
                for k in range(i1_, i2_):
                    lines.append("-" + a[k])
            elif tag == 'insert':
                for k in range(j1_, j2_):
                    lines.append("+" + b[k])
            elif tag == 'replace':
                for k in range(i1_, i2_):
                    lines.append("-" + a[k])
                for k in range(j1_, j2_):
                    lines.append("+" + b[k])

    return lines
