from collections import OrderedDict, defaultdict

class LFUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.key_value = {}
        self.key_freq = {}
        self.freq_keys = defaultdict(OrderedDict)
        self.min_freq = 0

    def _touch(self, key):
        freq = self.key_freq[key]
        del self.freq_keys[freq][key]
        if not self.freq_keys[freq]:
            del self.freq_keys[freq]
            if self.min_freq == freq:
                self.min_freq += 1
        new_freq = freq + 1
        self.key_freq[key] = new_freq
        self.freq_keys[new_freq][key] = None

    def get(self, key):
        if key not in self.key_value:
            return -1
        self._touch(key)
        return self.key_value[key]

    def put(self, key, value):
        if self.capacity <= 0:
            return

        if key in self.key_value:
            self.key_value[key] = value
            self._touch(key)
            return

        if len(self.key_value) >= self.capacity:
            evict_key, _ = self.freq_keys[self.min_freq].popitem(last=False)
            if not self.freq_keys[self.min_freq]:
                del self.freq_keys[self.min_freq]
            del self.key_value[evict_key]
            del self.key_freq[evict_key]

        self.key_value[key] = value
        self.key_freq[key] = 1
        self.freq_keys[1][key] = None
        self.min_freq = 1
