def topk(stream, k):
    if k <= 0:
        return []

    heap = []  # min-heap of (value, -index, label), size <= k (temporarily k+1)
    for index, (value, label) in enumerate(stream):
        item = (value, -index, label)
        if len(heap) < k:
            heapq.heappush(heap, item)
        else:
            if item > heap[0]:
                heapq.heapreplace(heap, item)

    # Sort by value descending, ties by arrival order ascending (-x[1] == index)
    ordered = sorted(heap, key=lambda x: (-x[0], -x[1]))
    return [(v, label) for v, neg_idx, label in ordered]
