            if not step_s.isdigit() or int(step_s) <= 0:
                raise ValueError(f"Malformed cron field: {field!r}")
            step = int(step_s)
        else:
            base = part

        if base == '*':
            start, end = min_v, max_v
        elif '-' in base:
            bounds = base.split('-')
            if len(bounds) != 2:
                raise ValueError(f"Malformed cron field: {field!r}")
            a, b = bounds
            if not a.isdigit() or not b.isdigit():
                raise ValueError(f"Malformed cron field: {field!r}")
            start, end = int(a), int(b)
            if start > end or start < min_v or end > max_v:
                raise ValueError(f"Malformed cron field: {field!r}")
        else:
