                raise ValueError(f"Malformed cron field: {field!r}")
            start = end = int(base)
            if start < min_v or start > max_v:
                raise ValueError(f"Malformed cron field: {field!r}")

        for v in range(start, end + 1, step):
            values.add(v)

    if not values:
        raise ValueError(f"Malformed cron field: {field!r}")

    return values


