def wildcard_match(pattern, s):
    n, m = len(pattern), len(s)
    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = True
    for i in range(1, n + 1):
        if pattern[i - 1] == '*':
            dp[i][0] = dp[i - 1][0]
    for i in range(1, n + 1):
        pc = pattern[i - 1]
        for j in range(1, m + 1):
            if pc == '*':
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
            elif pc == '?' or pc == s[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = False
    return dp[n][m]
