        |(?P<PLUS>\+)
        |(?P<MINUS>-)
        |(?P<MUL>\*)
        |(?P<DIV>/)
        |(?P<MOD>%)
        |(?P<LPAREN>\()
        |(?P<RPAREN>\))
        )
    ''', re.VERBOSE)

    tokens = []
