                op = self.advance()[0]
                right = self.parse_factor()
                if op == 'MUL':
                    value = value * right
                elif op == 'DIV':
                    if right == 0:
                        raise ValueError("Division by zero")
                    value = value / right
                else:
                    if right == 0:
                        raise ValueError("Modulo by zero")
                    value = value % right
