from sortedcontainers import SortedList

def window_medians(a, k):
    n = len(a)
    if k > n or k <= 0:
        return []
    sl = SortedList(a[:k])
    result = []

    def get_median():
        if k % 2 == 1:
            return float(sl[k // 2])
        else:
            return (sl[k // 2 - 1] + sl[k // 2]) / 2.0

    result.append(get_median())
    for i in range(k, n):
        sl.add(a[i])
        sl.remove(a[i - k])
        result.append(get_median())
    return result
