def to_base(n, alphabet):
    base = len(alphabet)
    if n == 0:
        return alphabet[0]
    neg = n < 0
    n = abs(n)
    digits = []
    while n > 0:
        n, r = divmod(n, base)
        digits.append(alphabet[r])
    if neg:
        digits.append('-')
    return ''.join(reversed(digits))


def from_base(s, alphabet):
    if not s:
        raise ValueError("empty string")
    neg = False
    if s[0] == '-':
        neg = True
        s = s[1:]
        if not s:
            raise ValueError("empty string after '-'")
    base = len(alphabet)
    index = {c: i for i, c in enumerate(alphabet)}
    result = 0
    for ch in s:
        if ch not in index:
            raise ValueError(f"invalid character: {ch}")
        result = result * base + index[ch]
    return -result if neg else result
