class Emitter {
  constructor() {
    this._events = new Map();
  }

  on(event, fn) {
    if (!this._events.has(event)) {
      this._events.set(event, []);
    }
    const listeners = this._events.get(event);
    const wrapper = { fn, once: false };
    listeners.push(wrapper);
    return () => {
      this.off(event, fn, wrapper);
    };
  }

  once(event, fn) {
    if (!this._events.has(event)) {
      this._events.set(event, []);
    }
    const listeners = this._events.get(event);
    const wrapper = { fn, once: true };
    listeners.push(wrapper);
    return () => {
      this.off(event, fn, wrapper);
    };
  }

  off(event, fn, wrapper) {
    const listeners = this._events.get(event);
    if (!listeners) return;
    let idx = -1;
    if (wrapper) {
      idx = listeners.indexOf(wrapper);
    } else {
      idx = listeners.findIndex(l => l.fn === fn);
    }
    if (idx !== -1) {
      listeners.splice(idx, 1);
    }
  }

  emit(event, ...args) {
    const listeners = this._events.get(event);
    if (!listeners || listeners.length === 0) return 0;

    const snapshot = listeners.slice();
    let count = 0;
    let firstError = null;

    for (const wrapper of snapshot) {
      const currentListeners = this._events.get(event);
      if (!currentListeners || !currentListeners.includes(wrapper)) {
        continue;
      }

      if (wrapper.once) {
        const idx = currentListeners.indexOf(wrapper);
        if (idx !== -1) {
          currentListeners.splice(idx, 1);
        }
      }

      try {
        wrapper.fn.apply(this, args);
        count++;
      } catch (err) {
        if (firstError === null) {
          firstError = err;
        }
        count++;
      }
    }

    if (firstError !== null) {
      throw firstError;
    }

    return count;
  }
}

