function sqlTag(strings, ...values) {
  let text = strings[0];
  const outValues = [];

  for (let i = 0; i < values.length; i++) {
    const val = values[i];

    if (val && typeof val === 'object' && typeof val.text === 'string' && Array.isArray(val.values)) {
      // Inline nested sqlTag result, renumbering its placeholders
      const offset = outValues.length;
      const renumbered = val.text.replace(/\$(\d+)/g, (match, num) => {
        return '$' + (parseInt(num, 10) + offset);
      });
      text += renumbered;
      outValues.push(...val.values);
    } else if (Array.isArray(val)) {
      const placeholders = val.map((v) => {
        outValues.push(v);
        return '$' + outValues.length;
      });
      text += '(' + placeholders.join(', ') + ')';
    } else {
      outValues.push(val);
      text += '$' + outValues.length;
    }

    text += strings[i + 1];
  }

  return { text, values: outValues };
}

