async function* chunkAsync(source, size) {
  if (!Number.isInteger(size) || size <= 0) {
    throw new RangeError('size must be a positive integer');
  }

  const iterator =
    (source[Symbol.asyncIterator] && source[Symbol.asyncIterator]()) ||
    (source[Symbol.iterator] && source[Symbol.iterator]());

  if (!iterator) {
    throw new TypeError('source is not iterable or async iterable');
  }

  let chunk = [];

  try {
    while (true) {
      const { value, done } = await iterator.next();

      if (done) {
        if (chunk.length > 0) {
          yield chunk;
        }
        return;
      }

      chunk.push(value);

      if (chunk.length === size) {
        yield chunk;
        chunk = [];
      }
    }
  } finally {
    if (typeof iterator.return === 'function') {
      await iterator.return();
    }
  }
}

