function zipLongest(fill, ...iterables) {
  return {
    [Symbol.iterator]() {
      if (iterables.length === 0) {
        return {
          next() {
            return { value: undefined, done: true };
          }
        };
      }

      const iterators = iterables.map(it => it[Symbol.iterator]());
      const finished = new Array(iterators.length).fill(false);

      return {
        next() {
          if (finished.every(f => f)) {
            return { value: undefined, done: true };
          }

          const row = new Array(iterators.length);
          let anyActive = false;

          for (let i = 0; i < iterators.length; i++) {
            if (finished[i]) {
              row[i] = fill;
              continue;
            }
            const result = iterators[i].next();
            if (result.done) {
              finished[i] = true;
              row[i] = fill;
            } else {
              row[i] = result.value;
              anyActive = true;
            }
          }

          if (!anyActive) {
            return { value: undefined, done: true };
          }

          return { value: row, done: false };
        }
      };
    }
  };
}

