type EmitArgs<E extends Record<string, unknown>, K extends keyof E> =
  E[K] extends void ? [payload?: undefined] : [payload: E[K]];

export class Bus<E extends Record<string, unknown>> {
  private listeners: {
    [K in keyof E]?: Array<(payload: E[K]) => void>;
  } = {};

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    if (!this.listeners[k]) {
      this.listeners[k] = [];
    }
    const arr = this.listeners[k]!;
    arr.push(fn);
    return () => {
      const idx = arr.indexOf(fn);
      if (idx !== -1) {
        arr.splice(idx, 1);
      }
    };
  }

  emit<K extends keyof E>(k: K, ...args: EmitArgs<E, K>): void {
    const arr = this.listeners[k];
    if (!arr) return;
    const payload = args[0] as E[K];
    for (const fn of [...arr]) {
      fn(payload);
    }
  }
