  : T;

export async function deepAwait<T>(value: T): Promise<DeepAwaited<T>> {
  const resolved: any = await value;

  if (resolved === null || resolved === undefined) {
    return resolved as DeepAwaited<T>;
  }

  if (typeof resolved === "function") {
    return resolved as DeepAwaited<T>;
  }

  if (Array.isArray(resolved)) {
    const mapped = await Promise.all(
      resolved.map((item: unknown) => deepAwait(item))
    );
    return mapped as DeepAwaited<T>;
  }

  if (typeof resolved === "object") {
    const keys = Object.keys(resolved);
    const values = await Promise.all(
      keys.map((key) => deepAwait(resolved[key]))
    );
    const result: Record<string, unknown> = {};
    for (let i = 0; i < keys.length; i++) {
      result[keys[i]] = values[i];
    }
    return result as DeepAwaited<T>;
  }

  return resolved as DeepAwaited<T>;
}
