  return r.kind === 'ok';
}

export function isErr<T, E>(r: Result<T, E>): r is Err<E> {
  return r.kind === 'err';
}

export function map<T, U, E>(r: Result<T, E>, f: (value: T) => U): Result<U, E> {
  if (isOk(r)) {
    return ok(f(r.value));
  }
  return r;
}

export function unwrapOr<T, E>(r: Result<T, E>, defaultValue: T): T {
  if (isOk(r)) {
    return r.value;
  }
  return defaultValue;
}
