type ExtractParams<S extends string> =
  S extends `${infer _Start}:${infer Param}/${infer Rest}`
    ? Param | ExtractParams<`/${Rest}`>
    : S extends `${infer _Start}:${infer Param}`
      ? Param
      : never;

type ParamsObject<S extends string> = {
  [K in ExtractParams<S>]: string;
};

type RouteFn<S extends string> = ExtractParams<S> extends never
  ? () => string
  : (params: ParamsObject<S>) => string;

type RouteMap = Record<string, string>;

type DefinedRoutes<T extends RouteMap> = {
  [K in keyof T]: RouteFn<T[K]>;
};

export function defineRoutes<T extends RouteMap>(routes: T): DefinedRoutes<T> {
  const result: Record<string, (params?: Record<string, string>) => string> = {};

  for (const key in routes) {
    if (Object.prototype.hasOwnProperty.call(routes, key)) {
      const template = routes[key];
      result[key] = (params?: Record<string, string>): string => {
        return template.replace(/:([A-Za-z0-9_]+)/g, (_match, paramName: string) => {
          if (!params || !(paramName in params)) {
            throw new Error(`Missing parameter "${paramName}" for route "${key}"`);
          }
          return params[paramName];
        });
      };
    }
  }

  return result as DefinedRoutes<T>;
}
