export type DeepPartial<T> = T extends (...args: any[]) => any
  ? T
  : T extends Array<infer U>
  ? Array<U>
  : T extends ReadonlyArray<infer U>
  ? ReadonlyArray<U>
  : T extends object
  ? { [K in keyof T]?: DeepPartial<T[K]> }
  : T;

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  if (Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  if (!isPlainObject(base) || !isPlainObject(patch)) {
    return (patch === undefined ? base : (patch as unknown as T));
  }

  const result: Record<string, unknown> = { ...base };
  const patchObj = patch as Record<string, unknown>;

  for (const key of Object.keys(patchObj)) {
    const patchValue = patchObj[key];
    if (patchValue === undefined) {
      continue;
    }

    const baseValue = (base as Record<string, unknown>)[key];

    if (Array.isArray(patchValue)) {
      result[key] = patchValue;
    } else if (isPlainObject(patchValue) && isPlainObject(baseValue)) {
      result[key] = applyPatch(baseValue, patchValue as DeepPartial<unknown>);
    } else {
      result[key] = patchValue;
    }
  }

  return result as T;
}
